import { config } from "dotenv";
import express from "express";
import cors from "cors";
import cookieParser from "cookie-parser";

import { authRouter } from "@/features/auth/routes";

config();

const app = express();

app.use(
  cors({
    origin: process.env.CORS_ORIGIN,
    credentials: true,
    optionsSuccessStatus: 200,
  })
);
app.use(express.json());
app.use(cookieParser());

app.use("/auth", authRouter);

const PORT = process.env.PORT || 4000;

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

import express from "express";

import { validate } from "@/features/auth/middlewares/validate";
import { auth } from "@/features/auth/middlewares/auth";
import { magicLinkSchema } from "@/features/auth/validation/magicLink";

import { magicLinkHandler } from "@/features/auth/controllers/magicLinkHandler";
import { verifyMagicLinkHandler } from "@/features/auth/controllers/verifyMagicLinkHandler";
import { meHandler } from "@/features/auth/controllers/meHandler";
import { logoutHandler } from "@/features/auth/controllers/logoutHandler";

const authRouter = express.Router();

authRouter.post("/magic-link", validate(magicLinkSchema), magicLinkHandler);
authRouter.post("/verify-magic-link", verifyMagicLinkHandler);
authRouter.get("/me", auth, meHandler);
authRouter.post("/logout", auth, logoutHandler);

export { authRouter };

import { Request, Response, NextFunction } from "express";
import { ZodSchema } from "zod";

export const validate =
  (schema: ZodSchema) =>
  (req: Request, res: Response, next: NextFunction) => {
    const result = schema.safeParse(req.body);

    if (!result.success) {
      return res.status(400).json({
        message: "Validation failed",
        errors: result.error.flatten().fieldErrors,
      });
    }

    req.body = result.data;
    return next();
  };

import { Request, Response, NextFunction } from "express";
import { verifyToken } from "@/features/auth/utils/tokens";

export const auth = (req: Request, res: Response, next: NextFunction) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ message: "Unauthorized" });
  }

  const token = authHeader.split(" ")[1];

  try {
    const decoded = verifyToken(token, String(process.env.JWT_SECRET)) as {
      userId: string;
    };
    (req as any).userId = decoded.userId;
    return next();
  } catch {
    return res.status(401).json({ message: "Unauthorized" });
  }
};

import { Request, Response } from "express";
import { prisma } from "@/config";
import { generateMagicLinkToken } from "@/features/auth/utils/tokens";
import { sendMagicLink } from "@/features/auth/utils/email";

export const magicLinkHandler = async (req: Request, res: Response) => {
  const { email } = req.body;

  let user = await prisma.user.findUnique({
    where: { email },
  });

  if (!user) {
    user = await prisma.user.create({
      data: { email },
    });
  }

  const token = generateMagicLinkToken(user.id);

  await sendMagicLink(email, token);

  return res.json({ message: "Magic link sent" }).status(200);
};

import { Request, Response } from "express";
import { prisma } from "@/config";
import { verifyToken, generateAccessToken, generateRefreshToken } from "@/features/auth/utils/tokens";

export const verifyMagicLinkHandler = async (req: Request, res: Response) => {
  const { token } = req.body;

  if (!token) {
    return res.status(400).json({ message: "Token is required" });
  }

  try {
    const decoded = verifyToken(token, String(process.env.MAGIC_LINK_SECRET)) as {
      userId: string;
    };

    const user = await prisma.user.findUnique({
      where: { id: decoded.userId },
      select: { id: true, name: true, email: true },
    });

    if (!user) {
      return res.status(404).json({ message: "User not found" });
    }

    const accessToken = generateAccessToken(user.id);
    const refreshToken = generateRefreshToken(user.id);

    const isProd = process.env.NODE_ENV === "production";
    res.cookie("refreshToken", refreshToken, {
      httpOnly: true,
      sameSite: "lax",
      maxAge: 7 * 24 * 60 * 60 * 1000,
      secure: isProd,
    });

    return res.json({ user, accessToken }).status(200);
  } catch {
    return res.status(401).json({ message: "Invalid or expired token" });
  }
};

import { Request, Response } from "express";
import { prisma } from "@/config";

export const meHandler = async (req: Request, res: Response) => {
  const userId = (req as any).userId;

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { id: true, name: true, email: true },
  });

  return res.json(user).status(200);
};

import { Request, Response } from "express";

export const logoutHandler = async (req: Request, res: Response) => {
  res.clearCookie("refreshToken");
  return res.json({ message: "Logged out successfully" }).status(200);
};

import { z } from "zod";

export const magicLinkSchema = z.object({
  email: z.string().email(),
});

export type MagicLinkInput = z.infer<typeof magicLinkSchema>;

import jwt from "jsonwebtoken";

export function generateAccessToken(userId: string): string {
  return jwt.sign({ userId }, String(process.env.JWT_SECRET), {
    expiresIn: "15m",
  });
}

export function generateRefreshToken(userId: string): string {
  return jwt.sign({ userId }, String(process.env.JWT_REFRESH_SECRET), {
    expiresIn: "7d",
  });
}

export function generateMagicLinkToken(userId: string): string {
  return jwt.sign({ userId }, String(process.env.MAGIC_LINK_SECRET), {
    expiresIn: "15m",
  });
}

export function verifyToken(token: string, secret: string): unknown {
  return jwt.verify(token, secret);
}

import nodemailer from "nodemailer";

const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST,
  port: Number(process.env.SMTP_PORT ?? 587),
  auth: {
    user: process.env.SMTP_USER,
    pass: process.env.SMTP_PASS,
  },
});

export async function sendMagicLink(email: string, token: string): Promise<void> {
  const frontendUrl = String(process.env.FRONTEND_URL ?? "http://localhost:3000");
  const link = `${frontendUrl}/verify?token=${token}`;

  await transporter.sendMail({
    from: process.env.SMTP_USER,
    to: email,
    subject: "Your magic link",
    html: `<p>Click <a href="${link}">here</a> to log in.</p>`,
  });
}
